import './realtor-runtime-20261015.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-batch-20261016';const launch=JSON.parse(await fs.readFile(dir+'/monitor-launch.json'));process.kill(launch.pid,'SIGTERM');await new Promise(r=>setTimeout(r,1000));try{process.kill(launch.pid,0);throw Error('Monitor still running')}catch(e){if(e.code!=='ESRCH')throw e;}await fs.unlink(dir+'/monitor.lock').catch(e=>{if(e.code!=='ENOENT')throw e;});
let jobs=[];for(let offset=0;;offset+=1000){const page=await db('sequence_jobs',{'sms_payload->>campaign_key':'eq.gta-20261016-intro-v1',status:'eq.pending',order:'scheduled_at.asc,id.asc',limit:'1000',offset:String(offset)});jobs.push(...page);if(page.length<1000)break;}
const start=Date.now()+5*60000;const planned=jobs.map((j,i)=>({id:j.id,contact_id:j.contact_id,old:j.scheduled_at,next:new Date(start+i*5000).toISOString()}));if(Date.parse(planned.at(-1).next)>Date.parse('2026-10-16T16:35:00Z'))throw Error('Cannot meet desired initial-send buffer');await fs.writeFile(dir+'/accelerated-schedule-plan.json',JSON.stringify({at:new Date().toISOString(),target_delivery_deadline:'2026-10-16T17:30:00Z',spacing_ms:5000,rows:planned},null,2),{flag:'wx'});
const changed=[];for(let i=0;i<planned.length;i+=10){const results=await Promise.allSettled(planned.slice(i,i+10).map(async p=>{const r=await db('sequence_jobs',{id:'eq.'+p.id,status:'eq.pending',provider_sid:'is.null',scheduled_at:'eq.'+p.old},'PATCH',{scheduled_at:p.next});if(r.length>1)throw Error('Unexpected count');return{...p,updated:r.length===1};}));for(const r of results){if(r.status==='rejected')throw r.reason;changed.push(r.value);}await fs.writeFile(dir+'/accelerated-schedule-receipt.json',JSON.stringify(changed));}
const byContact=new Map(changed.filter(r=>r.updated).map(r=>[r.contact_id,r]));for(const f of (await fs.readdir(dir)).filter(f=>/^release-.*-receipt\.json$/.test(f))){const path=dir+'/'+f;const old=await fs.readFile(path,'utf8');await fs.writeFile(path+'.before-acceleration',old,{flag:'wx'});const r=JSON.parse(old);for(const row of r.rows){const p=byContact.get(row.contact_id);if(p)row.scheduled_at=p.next;}await fs.writeFile(path,JSON.stringify(r,null,2));}
console.log(JSON.stringify({changed:changed.filter(r=>r.updated).length,already_claimed:changed.filter(r=>!r.updated).length,first:planned[0].next,last:planned.at(-1).next}));
